import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long[] gas = new long[(int) n];
        for (int i = 0; i < gas.length; i++) gas[i] = Long.parseLong(next());
        long[] cost = new long[(int) n];
        for (int i = 0; i < cost.length; i++) cost[i] = Long.parseLong(next());

        long total = 0, tank = 0, start = 0;
        for (int i = 0; i < n; i++) {
            long d = gas[i] - cost[i];
            total += d;
            tank += d;
            if (tank < 0) {
                start = i + 1;
                tank = 0;
            }
        }
        System.out.println(total >= 0 ? start : -1);
    }
}
